// See https://tilings.math.uni-bielefeld.de/substitution/ammann-chair/

const mat2 rot90 = mat2(0.0, 1.0, -1.0, 0.0); // column major!
const mat2 rot270 = mat2(0.0, -1.0, 1.0, 0.0); // column major!

mat2 rot(float theta) {
    float s = sin(theta);
    float c = cos(theta);
    return mat2(s, c, -c, s); // column major!
}

const float phi = (1.0 + sqrt(5.0)) * 0.5;
const float k = sqrt(phi);

const float tau = 6.283185307179586;

bool validp(vec2 p) {
    return    0.0 <= p.x 
           && 0.0 <= p.y
           && p.x <= phi 
           && p.y <= k*phi 
           && (p.x <= 1.0 || p.y <= k);
}

// Smooth HSV to RGB conversion (https://www.shadertoy.com/view/MsS3Wc)
vec3 hsv2rgb_smooth( in vec3 c )
{
    vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
	rgb = rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	
	return c.z * mix( vec3(1.0), rgb, c.y);
}

#define C0 vec4(0.2, 0.2, 0.4, 1.0) * 1.4 // dark blue
#define C1 vec4(0.8, 0.7, 0.3, 1.0) // dark yellow
#define C2 vec4(0.8, 0.2, 0.4, 1.0) // dark red
#define WHITE vec4(1.0, 1.0, 1.0, 1.0)
#define BLACK vec4(0.0, 0.0, 0.0, 1.0)


// distance from an edge
float edge_distance(vec2 a, vec2 b, vec2 p) {
    vec2 ab = b - a;
    float abdist = length(ab);
    vec2 abperp = vec2(- ab.y, ab.x) / abdist;
    vec2 ap = p - a;
    float apDotab = dot(ap, ab);
    if (apDotab < 0.0) { return length(ap); }
    if (apDotab > abdist * abdist) { return length(p - b); }
    return abs(dot(abperp, ap));
}


// a measure of distance from the edges of the unit tile
float distance_to_tile_edge(vec2 p) {
    return min (edge_distance(vec2(0.0, 0.0), vec2(phi, 0.0), p),
           min (edge_distance(vec2(phi, 0.0), vec2(phi, k), p),
           min (edge_distance(vec2(phi, k), vec2(1.0, k), p),
           min (edge_distance(vec2(1.0, k), vec2(1.0, phi * k), p),
           min (edge_distance(vec2(1.0, phi * k), vec2(0.0, phi * k), p),
                edge_distance(vec2(0.0, phi * k), vec2(0.0, 0.0), p)
           )))));
}


// another measure of distance from the edges of the unit tile
float proximity_to_tile_edge2(vec2 p) {
  #define FN(x) (1.0/x)
    return (
          FN(edge_distance(vec2(0.0, 0.0), vec2(phi, 0.0), p))
        + FN(edge_distance(vec2(phi, 0.0), vec2(phi, k), p))
        + FN(edge_distance(vec2(phi, k), vec2(1.0, k), p))
        + FN(edge_distance(vec2(1.0, k), vec2(1.0, phi * k), p))
        + FN(edge_distance(vec2(1.0, phi * k), vec2(0.0, phi * k), p))
        + FN(edge_distance(vec2(0.0, phi * k), vec2(0.0, 0.0), p))
        );
  #undef FN
}


void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    // scale so that the initial tile (which will be the whole patch) 
    // is centred and covers at least the whole display.
    vec2 p = rot(fract(iTime / 10.0) * tau) * (fragCoord - iResolution.xy*0.5);

    float scale = max(iResolution.x * k, iResolution.y) * 1.5;
    p = (p / scale + 0.5*vec2(phi, phi*k));
    p = p;
    //p = p * 4.0/*DEBUG*/;// * 3.0;

    vec4 colour = BLACK;
    fragColour = colour;

    // pixels outside the tile are left black
    if (!validp(p)) { return; }

    int tile_type = 0; 

    for (int iround = 0; iround < int(round(GET(ROUNDSloc).x)); ++iround) {

        st_assert(validp(p), 1);

        if (tile_type == 0) {
            colour = C1;
            tile_type = 1;

        } else if (p.y > k || (p.y > 1.0 / k && p.x < 1.0 / phi)) {
            colour = C2;
            p.y = k * phi - p.y; 
            p = p * phi;
            tile_type = 0;
            st_assert(validp(p), 1);

        } else {
            colour = C1;
            p = (rot270 * p + vec2(0.0, phi)) * k;
            tile_type = 1;
            st_assert(validp(p), 2);
        }

    }

  int colour_scheme = int(round(GET(COLOURSCHEMEloc).x));
  if (colour_scheme == 0) {

    vec4 base_colour = (tile_type == 0) ? C0 : C1;

  } else if (colour_scheme == 1) {

    vec4 base_colour = (tile_type == 0) ? C0 : C1;
    float d = distance_to_tile_edge(p);
    colour = mix(base_colour, WHITE, sqrt(d));

  } else { // colour_scheme >= 2

    vec4 base_colour = (tile_type == 0) ? C0 : C1;
    float d = proximity_to_tile_edge2(p);
    float border = smoothstep(14.0, 15.0, d / 1.5);
    colour = BLACK; //mix(WHITE, BLACK, border); 
    // fragColour=colour; return;

        vec4 hue;
        vec3 c1hsv = vec3(0.0, 1.0, 1.0);
        vec3 c2hsv = vec3(1.0, 1.0, 1.0);
        //colour = base_colour; // mix(base_colour, WHITE, sqrt(d));
        float offset = fract(iTime / 4.0);
        if (tile_type == 0) {
                hue = vec4(hsv2rgb_smooth(vec3(offset + d / 3.0, 1.0, 1.0)), 1.0);
        } else {
                hue = vec4(hsv2rgb_smooth(vec3(1.0 - offset + 0.5 + d / 3.0, 1.0, 1.0)), 1.0);
        }
        colour = mix(colour, hue, 1.0 - border);    
  }

fragColour = colour;

}

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    ivec2 uv = ivec2(fragCoord);
    vec4 value = GET(uv);

    if (iFrame < 4) {
        // Init
        value = vec4(0.0);
        if (uv == ROUNDSloc) {
            value.x = 6.0;
        } else if (uv == COLOURSCHEMEloc) {
            value.x = 2.0;
        }

    } else {
        // Run

        if (uv == ROUNDSloc) {
          if (texelFetch(iChannel3, ivec2(UP, 1), 0).x > 0.0) {
            value.x = value.x + 1.0;
          }
          if (texelFetch(iChannel3, ivec2(DOWN, 1), 0).x > 0.0) {
            value.x = max(0.0, value.x - 1.0);
          }
          if (iMouse.z > 0.0) {
            value.x = round(20.0 * iMouse.x / iResolution.x);
          }
        }

        if (uv == COLOURSCHEMEloc) {
          if (texelFetch(iChannel3, ivec2(LEFT, 1), 0).x > 0.0) {
            value.x = mod(N_COLOURSCHEMES + value.x - 1.0, N_COLOURSCHEMES);
          }
          if (texelFetch(iChannel3, ivec2(RIGHT, 1), 0).x > 0.0) {
            value.x = mod(value.x + 1.0, N_COLOURSCHEMES);
          }
          if (iMouse.z > 0.0) {
            value.x = round(N_COLOURSCHEMES * iMouse.y / iResolution.y);
          }
        }

    }

    fragColour = value;
}
